import { createRequire } from 'node:module';
import assert from 'node:assert/strict';
const require=createRequire(import.meta.url);
const E=require('../js/nagweb-interaction-engine-v1.js');
assert.equal(E.version,'1.0.0');
const o=E.normalizeOptions({follow:99,damping:-1,maxSpeed:0,tilt:90,minScale:2,maxScale:1});
assert.equal(o.follow,.65);assert.equal(o.damping,0);assert.equal(o.maxSpeed,.5);assert.equal(o.tilt,45);assert.ok(o.minScale<=o.maxScale);
const bounds={x:0,y:0,width:1000,height:700};
let s=E.createState(500,350);
for(let i=0;i<120;i++) E.step(s,{x:850,y:500},bounds,E.normalizeOptions({idle:{enabled:false}}),16.6667);
assert.ok(s.x>500&&s.y>350,'follower moves toward target');
assert.ok(Math.hypot(s.vx,s.vy)<=E.defaults.maxSpeed+0.001,'speed is capped');
const before={x:s.x,y:s.y};
for(let i=0;i<90;i++) E.step(s,{x:150,y:120},bounds,E.normalizeOptions({turnSmoothing:.08}),16.6667);
assert.ok(s.x<before.x,'follower can reverse direction smoothly');
const a=E.idleTarget(1000,bounds,E.normalizeOptions({idle:{enabled:true}}));
const b=E.idleTarget(5000,bounds,E.normalizeOptions({idle:{enabled:true}}));
assert.ok(a.x!==b.x||a.y!==b.y,'idle target changes over time');
const clamped=E.normalizeOptions({clampToBounds:true,padding:20});
let c=E.createState(990,690);c.vx=100;c.vy=100;E.step(c,{x:2000,y:2000},bounds,clamped,16.6667);
assert.ok(c.x<=980&&c.y<=680,'bounds clamp is respected');
console.log('NagWeb Interaction Engine V1 model tests: PASS');
